import unittest
from unittest import mock

from auth.sessions import Session


class FakeClock:
    def __init__(self, start=1000.0):
        self.now = start

    def __call__(self):
        return self.now


class SessionTests(unittest.TestCase):
    def setUp(self):
        self.clock = FakeClock()
        patcher = mock.patch("auth.sessions.time.monotonic", self.clock)
        patcher.start()
        self.addCleanup(patcher.stop)

    def test_new_session_is_active(self):
        self.assertFalse(Session("ada", ttl_seconds=900).is_expired())

    def test_session_is_active_just_before_its_ttl(self):
        session = Session("ada", ttl_seconds=900)
        self.clock.now += 899.9
        self.assertFalse(session.is_expired())

    def test_session_expires_after_its_ttl(self):
        session = Session("ada", ttl_seconds=900)
        self.clock.now += 900
        self.assertTrue(session.is_expired())

    def test_touch_keeps_a_session_alive(self):
        session = Session("ada", ttl_seconds=900)
        self.clock.now += 600
        session.touch()
        self.clock.now += 600
        self.assertFalse(session.is_expired())


