import unittest

from orders.service import NotRefundable, OrderService
from orders.store import InMemoryOrderStore, Order


class RecordingGateway:
    """Stands in for the payment provider: records each refund instead of calling the network."""

    def __init__(self):
        self.refunds = []

    def refund(self, charge_id, amount_cents):
        self.refunds.append((charge_id, amount_cents))


class RefundTests(unittest.TestCase):
    def setUp(self):
        self.store = InMemoryOrderStore([Order("o-1", 2599, "ch_9"), Order("o-2", 1000, "ch_4", status="shipped")])
        self.gateway = RecordingGateway()
        self.service = OrderService(self.store, self.gateway)

    def test_refund_marks_the_order_refunded_in_the_store(self):
        self.service.refund("o-1")
        self.assertEqual(self.store.get("o-1").status, "refunded")

    def test_refund_sends_the_full_amount_once(self):
        self.service.refund("o-1")
        self.assertEqual(self.gateway.refunds, [("ch_9", 2599)])

    def test_an_order_that_is_not_paid_is_not_refundable(self):
        with self.assertRaises(NotRefundable):
            self.service.refund("o-2")
        self.assertEqual(self.store.get("o-2").status, "shipped")
        self.assertEqual(self.gateway.refunds, [])


